     "summary": "美国财政部长斯科特·贝森特日前在接受美国亚利桑那州地方电视台采访时说，随着地缘政治局势变化，今后越来越多能源运输将绕过霍尔木兹海峡。他认为，霍尔木兹海峡将逐步失去战略重要性。当地媒体报道，贝森特在采访中说，鉴于伊朗试图控制霍尔木兹海峡这条咽喉要道，海峡将无法回到过去的状态。他声称，在接下来两年时间里，海峡将变成一片普通水域，逐步变得不再那么重要。 （文章来源：财联社）",
